package cl.nexbyte.siger.institucional.nucleo;
import java.nio.file.Path;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import cl.nexbyte.siger.institucional.notificaciones.TareasPersonales;import cl.nexbyte.siger.institucional.robustez.FalloTecnico;
import static org.junit.jupiter.api.Assertions.*;import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;
class EquipoAgendaTest {
 @TempDir Path temp;DatosAvisosTest f;UUID cas,q;String col;EquipoCaso equipo;
 @BeforeEach void setup()throws Exception{String mysql=System.getProperty("siger.test.autoridad.mysql");f=new DatosAvisosTest(temp,mysql==null?null:mysql+"_u2?sslMode=DISABLED&allowPublicKeyRetrieval=true&connectTimeout=3000&socketTimeout=10000");col=f.cuenta("colaborador","UPR","DEMO_SEDE_A","PROFESIONAL","UNIDAD_SEDE");var u=f.core.u2();var sol=u.distribuir(f.a(f.dist),key(),f.d.nuevaWeb(),new NucleoU2.Encaminar(0,new NuevoDestino("UPR","DEMO_SEDE_A",f.head),"Clasificación sintética",null)).id();q=u.asumir(f.a(f.head),key(),sol,new NucleoU2.Asumir(0,f.prof,"Atención profesional",null)).id();cas=u.abrirCaso(f.a(f.head),key(),q,new NucleoU2.Apertura(0,f.prof,"Trabajo del equipo")).id();equipo=f.core.equipo();}
 @AfterEach void close(){if(f!=null)f.close();}
 UUID key(){return UUID.randomUUID();}long rev(){return f.d.db.sql.queryForObject("SELECT revision FROM core_case WHERE id=?",Long.class,cas.toString());}
 void denied(int s,Runnable r){assertEquals(s,assertThrows(FalloTecnico.class,r::run).status);}
 void join(){equipo.incorporar(f.a(f.prof),key(),cas,new EquipoCaso.Incorporar(rev(),col,"Apoyo local autorizado"));}
 TareasPersonales.Edicion edit(String responsible,boolean mandatory,long revision){return new TareasPersonales.Edicion(revision,"Llamar con objetivo concreto","Contacto sintético",f.tiempo.instant().plusSeconds(100),null,null,f.tiempo.instant().plusSeconds(500),null,"CASO",cas,responsible,mandatory,"Asignación fundada de tarea");}
 UUID tarea(String creator,String responsible,boolean mandatory){return f.tareas.crear(f.a(creator),key(),edit(responsible,mandatory,0)).id();}
 long tr(UUID task){return f.tareas.leer(f.a(f.head),task).revision();}
 @Test void equipoDaAccesoSoloAlCasoYNoCierreOReasignacion(){denied(404,()->f.core.caso(f.a(col),cas));denied(404,()->equipo.incorporar(f.a(col),key(),cas,new EquipoCaso.Incorporar(0,col,"No autoasignar")));denied(400,()->equipo.incorporar(f.a(f.prof),key(),cas,new EquipoCaso.Incorporar(0,f.otro,"Otra unidad requiere su propio circuito")));join();assertEquals(1,f.core.casos(f.a(col),"",0,20).total());f.core.actuar(f.a(col),key(),cas,new Decision(rev(),"Actuación del colaborador"));assertEquals(col,f.core.caso(f.a(col),cas).actuaciones().getFirst().autor());denied(409,()->f.core.revisarCaso(f.a(col),key(),cas,new Decision(rev(),"No es principal"),"SOLICITUD_TERMINO"));denied(404,()->f.core.asignar(f.a(col),key(),cas,new Asignacion(rev(),col,null)));denied(404,()->f.core.detalle(f.a(col),f.core.caso(f.a(col),cas).comunicacionId()));assertEquals(0,f.core.casos(f.a(f.ti),"",0,20).total());}
 @Test void tareaAdmiteDescripcionFechasYPrioridadOmitidasConEjecutorPropioPorDefecto(){var r=f.tareas.crear(f.a(f.prof),key(),new TareasPersonales.Edicion(0,"Objetivo concreto",null,null,null,null,null,null,"CASO",cas,null,true,null));var task=f.tareas.leer(f.a(f.prof),r.id());assertEquals(f.prof,task.responsable());assertEquals("",task.descripcion());assertNull(task.plazo());assertTrue(task.obligatoria());assertEquals("NORMAL",task.prioridad());}
 @Test void tareaCompartidaUnEjecutorYObligatoriedadPorAsignador(){join();var t=tarea(f.prof,col,true);assertEquals(f.prof,f.tareas.leer(f.a(col),t).creador());denied(403,()->f.tareas.estado(f.a(f.prof),key(),t,new TareasPersonales.Cambio(0,"COMPLETADA",true)));denied(403,()->f.tareas.editar(f.a(col),key(),t,edit(col,false,0)));f.tareas.estado(f.a(col),key(),t,new TareasPersonales.Cambio(0,"COMPLETADA",true));assertEquals("COMPLETADA",f.tareas.leer(f.a(f.prof),t).estado());assertEquals(0,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_action",Long.class));}
 @Test void obligatoriasBloqueanCierreYOrdinariasAdviertenSinFabricarCumplimiento(){join();var must=tarea(f.prof,col,true);var ordinary=tarea(col,col,false);f.tareas.estado(f.a(col),key(),must,new TareasPersonales.Cambio(0,"EN_CURSO",false));f.core.revisarCaso(f.a(f.prof),key(),cas,new Decision(rev(),"Solicita revisión"),"SOLICITUD_TERMINO");denied(409,()->f.core.revisarCaso(f.a(f.head),key(),cas,new Decision(rev(),"Pendiente obligatoria"),"CIERRE"));f.tareas.estado(f.a(col),key(),must,new TareasPersonales.Cambio(1,"COMPLETADA",true));f.core.revisarCaso(f.a(f.head),key(),cas,new Decision(rev(),"Revisión actual confirma"),"CIERRE");assertEquals("PENDIENTE",f.tareas.leer(f.a(col),ordinary).estado());assertEquals("ACTIVO",f.core.u2().requerimiento(f.a(f.head),q).get("state"));denied(409,()->tarea(col,col,false));denied(409,()->f.tareas.intento(f.a(col),key(),ordinary,new TareasPersonales.Intento(0,"No reactivar trabajo por agenda")));f.tareas.estado(f.a(col),key(),ordinary,new TareasPersonales.Cambio(0,"COMPLETADA",true));assertEquals("CERRADO",f.core.caso(f.a(f.head),cas).estado());}
 @Test void tar09TransfiereTodasNoTerminalesIncluidasDeColaboradoresYConservaMetadatos(){join();var own=tarea(f.prof,f.prof,true);var other=tarea(col,col,false);var done=tarea(col,col,false);f.tareas.estado(f.a(col),key(),done,new TareasPersonales.Cambio(0,"COMPLETADA",true));f.tareas.estado(f.a(col),key(),other,new TareasPersonales.Cambio(0,"EN_CURSO",false));f.tareas.intento(f.a(f.prof),key(),own,new TareasPersonales.Intento(0,"Sin respuesta, objetivo no alcanzado"));var before=f.tareas.leer(f.a(f.prof),own);f.core.asignar(f.a(f.head),key(),cas,new Asignacion(rev(),col,null));var after=f.tareas.leer(f.a(col),own);assertEquals(col,after.responsable());assertEquals(before.creador(),after.creador());assertEquals(before.recordatorio(),after.recordatorio());assertEquals(before.plazo(),after.plazo());assertTrue(after.obligatoria());assertEquals("EN_CURSO",f.tareas.leer(f.a(col),other).estado());assertEquals(1,f.tareas.intentos(f.a(col),own).size());assertEquals("COMPLETADA",f.tareas.leer(f.a(col),done).estado());assertEquals(3,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_task",Long.class));denied(404,()->f.tareas.leer(f.a(f.prof),own));var receipt=f.core.continuidad().caso(f.a(col),cas,true);assertNull(((Map<?,?>)((List<?>)receipt.get("asignacion")).getFirst()).get("acknowledged_ms"));}
 @Test void reintentoDeTareaConservaResultadoTrasRetiroDelEjecutorSinCrearOtra(){join();var command=key();var input=edit(col,false,0);var result=f.tareas.crear(f.a(f.prof),command,input);equipo.retirar(f.a(f.head),key(),cas,new EquipoCaso.Retirar(rev(),col,f.prof,"Retiro con pendientes resueltos"));assertEquals(result,f.tareas.crear(f.a(f.prof),command,input));assertEquals(1,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_task",Long.class));assertEquals(f.prof,f.tareas.leer(f.a(f.prof),result.id()).responsable());denied(400,()->f.tareas.crear(f.a(f.prof),key(),input));}
 @Test void retiroTrataPendientesAntesDeRevocarYConservaAutoria(){join();var t=tarea(col,col,false);denied(409,()->equipo.retirar(f.a(f.prof),key(),cas,new EquipoCaso.Retirar(rev(),col,null,"Retiro sin abandonar agenda")));assertNotNull(f.core.caso(f.a(col),cas));equipo.retirar(f.a(f.prof),key(),cas,new EquipoCaso.Retirar(rev(),col,f.prof,"Asume pendientes el principal"));denied(404,()->f.core.caso(f.a(col),cas));assertEquals(f.prof,f.tareas.leer(f.a(f.prof),t).responsable());assertEquals(col,f.tareas.leer(f.a(f.prof),t).creador());assertEquals("RETIRADO",((List<Map<String,Object>>)equipo.ver(f.a(f.prof),cas).get("miembros")).getFirst().get("state"));}
 @Test void intentoYReprogramacionNoCompletanNiCreanActuacion(){var t=tarea(f.prof,f.prof,false);var command=key();var r=new TareasPersonales.Intento(0,"Llamada sin respuesta");assertEquals(f.tareas.intento(f.a(f.prof),command,t,r),f.tareas.intento(f.a(f.prof),command,t,r));f.tareas.editar(f.a(f.prof),key(),t,edit(f.prof,false,1));assertEquals("PENDIENTE",f.tareas.leer(f.a(f.prof),t).estado());assertEquals(1,f.tareas.intentos(f.a(f.prof),t).size());assertEquals(0,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_action",Long.class));}
 @Test void rollbackTar09NoDejaNuevaAsignacionNiTransferenciasParciales(){join();var t=tarea(f.prof,f.prof,true);long initial=rev();f.d.ddl(st->st.execute("ALTER TABLE task_history ADD CONSTRAINT test_tar09_block CHECK(event_code<>'TAR09_TRASPASO_PENDIENTES')"));var command=key();try{assertThrows(org.springframework.dao.DataAccessException.class,()->f.core.asignar(f.a(f.head),command,cas,new Asignacion(initial,col,null)));}finally{f.d.ddl(st->st.execute("ALTER TABLE task_history DROP CONSTRAINT test_tar09_block"));}assertEquals(f.prof,f.core.caso(f.a(f.prof),cas).responsable());assertEquals(f.prof,f.tareas.leer(f.a(f.prof),t).responsable());assertEquals(initial,rev());f.core.asignar(f.a(f.head),command,cas,new Asignacion(initial,col,null));assertEquals(col,f.tareas.leer(f.a(col),t).responsable());}
 @Test void esperaConfirmadaConservaGestionYRequiereReanudarExplicitamente(){join();var p=equipo.solicitarEspera(f.a(col),key(),cas,new EquipoCaso.Espera(rev(),"Informe faltante","Contacto sintético",f.tiempo.instant()));denied(404,()->equipo.resolverEspera(f.a(col),key(),cas,p.id(),new EquipoCaso.ResolverEspera(0,rev(),"CONFIRMADA","No es jefatura")));equipo.resolverEspera(f.a(f.head),key(),cas,p.id(),new EquipoCaso.ResolverEspera(0,rev(),"CONFIRMADA","Espera fundada"));assertTrue(equipo.enEspera(cas));assertTrue(f.core.caso(f.a(col),cas).enEspera());assertEquals(1,f.core.casos(f.a(col),"EN_ESPERA",0,20).total());assertEquals(0,f.core.casos(f.a(f.otro),"EN_ESPERA",0,20).total());assertEquals(0,f.core.casos(f.a(f.ti),"EN_ESPERA",0,20).total());f.core.actuar(f.a(col),key(),cas,new Decision(rev(),"Seguimiento mientras espera"));denied(409,()->f.core.revisarCaso(f.a(f.prof),key(),cas,new Decision(rev(),"No cerrar espera"),"SOLICITUD_TERMINO"));equipo.resolverEspera(f.a(col),key(),cas,p.id(),new EquipoCaso.ResolverEspera(1,rev(),"FINALIZADA","Se recibió y evaluó el informe"));assertFalse(equipo.enEspera(cas));assertEquals(0,f.core.casos(f.a(col),"EN_ESPERA",0,20).total());assertEquals(f.prof,f.core.caso(f.a(col),cas).responsable());}
 @Test void carreraMarcarObligatoriaYCierreNoDejaCasoCerradoConPendiente()throws Exception{var t=tarea(f.prof,f.prof,false);f.core.revisarCaso(f.a(f.prof),key(),cas,new Decision(rev(),"Revisión de término"),"SOLICITUD_TERMINO");long v=rev();try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var close=pool.submit(()->{start.await();try{f.core.revisarCaso(f.a(f.head),key(),cas,new Decision(v,"Confirma"),"CIERRE");return true;}catch(FalloTecnico e){assertEquals(409,e.status);return false;}});var mark=pool.submit(()->{start.await();try{f.tareas.editar(f.a(f.prof),key(),t,edit(f.prof,true,0));return true;}catch(FalloTecnico e){assertEquals(409,e.status);return false;}});start.countDown();assertNotEquals(close.get(),mark.get());}assertFalse(f.core.caso(f.a(f.head),cas).estado().equals("CERRADO")&&equipo.obligatorias(cas));}
 @Test void recordatoriosCambianDeEjecutorSinDuplicarTareaNiReenviarAlAnterior(){join();var base=edit(f.prof,false,0);var t=f.tareas.crear(f.a(f.prof),key(),new TareasPersonales.Edicion(0,base.titulo(),base.descripcion(),f.tiempo.instant().minusSeconds(1),null,null,null,null,"CASO",cas,f.prof,false,null)).id();f.tareas.temporales();for(int i=0;i<3;i++)f.notices.proyectar();assertTrue(f.notices.listar(f.a(f.prof),0,50).items().stream().anyMatch(n->n.tipo().equals("TAREA_RECORDATORIO")));f.core.asignar(f.a(f.head),key(),cas,new Asignacion(rev(),col,null));equipo.incorporar(f.a(f.head),key(),cas,new EquipoCaso.Incorporar(rev(),f.prof,"Anterior principal colabora expresamente"));f.tareas.temporales();for(int i=0;i<3;i++)f.notices.proyectar();assertFalse(f.notices.listar(f.a(f.prof),0,50).items().stream().anyMatch(n->n.tipo().equals("TAREA_RECORDATORIO")));assertTrue(f.notices.listar(f.a(col),0,50).items().stream().anyMatch(n->n.tipo().equals("TAREA_RECORDATORIO")));f.tareas.temporales();for(int i=0;i<3;i++)f.notices.proyectar();assertEquals(2,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE category='TAREA_RECORDATORIO'",Long.class));assertEquals(1,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_task",Long.class));assertEquals(col,f.tareas.leer(f.a(col),t).responsable());}
 @Test void revocacionDeFacultadCierraColaboracionSinBorrarAutoria(){join();var t=tarea(col,col,false);f.core.actuar(f.a(col),key(),cas,new Decision(rev(),"Autoría conservada"));var account=f.ids.cuentas(f.ti).stream().filter(x->x.id().equals(col)).findFirst().orElseThrow();ConcesionFixture.revocar(f.d.db,f.ids,f.ti,col,account.asignaciones().getFirst().get("id").toString(),f.tiempo);denied(404,()->f.core.caso(f.a(col),cas));assertEquals(0,f.core.casos(f.a(col),"",0,20).total());denied(404,()->f.tareas.leer(f.a(col),t));equipo.retirar(f.a(f.head),key(),cas,new EquipoCaso.Retirar(rev(),col,f.prof,"Regulariza pendientes tras revocación"));assertEquals(col,f.core.caso(f.a(f.prof),cas).actuaciones().getFirst().autor());assertEquals(f.prof,f.tareas.leer(f.a(f.prof),t).responsable());}
 @Test void cambiosDeAgendaDuranteRevisionConservanModalidadDerivacionSinReinterpretarCierres(){var task=tarea(f.prof,f.prof,true);var target=new NuevoDestino("UPD","DEMO_SEDE_A",f.headOtra);var p=f.core.continuidad().derivar(f.a(f.head),key(),cas,new ContinuidadU2.Derivar(rev(),target,"Derivación expresa","Paquete limitado","Objetivo del sucesor"));f.core.continuidad().decidirDerivacion(f.a(f.headOtra),key(),p.id(),new ContinuidadU2.Resolver(0,"ACEPTADA",f.otro,"Acepta destino"));f.core.continuidad().solicitarCierreDerivacion(f.a(f.prof),key(),cas,new Decision(rev(),"Solicita cierre por derivación"));long requested=rev();f.tareas.estado(f.a(f.prof),key(),task,new TareasPersonales.Cambio(0,"COMPLETADA",true));assertEquals(1,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_case_closure_request WHERE case_id=? AND case_revision=?",Long.class,cas.toString(),requested));f.core.revisarCaso(f.a(f.head),key(),cas,new Decision(rev(),"Confirma sobre revisión actualizada"),"CIERRE");assertEquals("DERIVACION",f.core.caso(f.a(f.prof),cas).modalidadCierre());denied(409,()->f.core.continuidad().solicitarReapertura(f.a(f.prof),key(),cas,new ContinuidadU2.Reabrir(rev(),"No atajo por cambio de agenda","Antecedentes para el sucesor")));}
 @Test void sucesorNoCopiaEquipoNiTareasYTransferenciaPrincipalNoEjecutaTar09(){join();var task=tarea(col,col,false);var target=new NuevoDestino("UPD","DEMO_SEDE_A",f.headOtra);var tr=f.core.continuidad().transferir(f.a(f.head),key(),q,new ContinuidadU2.Trasladar(1,target,"Transferencia principal expresa","Paquete mínimo"));f.core.continuidad().decidirTransferencia(f.a(f.headOtra),key(),tr.id(),new ContinuidadU2.Resolver(0,"ACEPTADA",null,"Acepta coordinación"));assertEquals(col,f.tareas.leer(f.a(col),task).responsable());var der=f.core.continuidad().derivar(f.a(f.head),key(),cas,new ContinuidadU2.Derivar(rev(),target,"Derivación autorizada","Resumen mínimo","Objetivo propio"));f.core.continuidad().decidirDerivacion(f.a(f.headOtra),key(),der.id(),new ContinuidadU2.Resolver(0,"ACEPTADA",f.otro,"Se acepta"));var successor=UUID.fromString(f.d.db.sql.queryForObject("SELECT successor_id FROM institution_case_derivation WHERE id=?",String.class,der.id().toString()));assertTrue(((List<?>)equipo.ver(f.a(f.otro),successor).get("miembros")).isEmpty());assertTrue(f.tareas.delCaso(f.a(f.otro),successor).isEmpty());denied(404,()->f.core.caso(f.a(col),successor));assertEquals(col,f.tareas.leer(f.a(col),task).responsable());assertEquals(q,f.core.caso(f.a(f.otro),successor).requerimientoId());}
 @Test void avisosDeEquipoLleganAlIntegranteSinOtorgarAccesoDespuesDelRetiro(){join();for(int i=0;i<3;i++)f.notices.proyectar();assertTrue(f.notices.listar(f.a(col),0,50).items().stream().anyMatch(n->n.tipo().equals("EQUIPO_ACTUALIZADO")));equipo.retirar(f.a(f.head),key(),cas,new EquipoCaso.Retirar(rev(),col,null,"Fin del apoyo"));for(int i=0;i<3;i++)f.notices.proyectar();assertTrue(f.notices.listar(f.a(col),0,50).items().stream().anyMatch(n->n.tipo().equals("EQUIPO_ACTUALIZADO")));denied(404,()->f.core.caso(f.a(col),cas));assertTrue(f.notices.listar(f.a(f.ti),0,50).items().isEmpty());}
}
